<script setup lang="ts">
import { ref,watch,onBeforeUnmount } from 'vue';import { useRouter } from 'vue-router';
import {copyText,goSaved,api,mutate,can,text,date,opts,useTask,type DTO,type Page} from './shared';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';import AdminDialog from '../../shared/ui/AdminDialog.vue';
const props=defineProps<{resource:DTO<'ResourceView'>}>();const emit=defineEmits<{changed:[]}>();const router=useRouter();const {busy,error,notice,run}=useTask(),{form,open}=useForm();
const rows=ref<DTO<'Stage2CredentialMetadata'>[]>([]),page=ref(1),total=ref(0),more=ref(false),grants=ref<DTO<'Stage2CredentialGrantView'>[]>([]),grantCredential=ref<DTO<'Stage2CredentialMetadata'>>(),grantPage=ref(1),grantTotal=ref(0),grantMore=ref(false),secret=ref(''),revealed=ref(false);let timer:ReturnType<typeof setTimeout>;
function hide(){secret.value='';revealed.value=false;clearTimeout(timer);}function visibility(){if(document.hidden)hide();}document.addEventListener('visibilitychange',visibility);onBeforeUnmount(()=>{hide();document.removeEventListener('visibilitychange',visibility);});
async function load(){await run(async()=>{const d=await api.get<Page<DTO<'Stage2CredentialMetadata'>>>(`/resources/${props.resource.id}/credentials?page=${page.value}`);rows.value=d.items;total.value=d.pagination.total;more.value=d.pagination.has_next;});}
watch(()=>props.resource.id,()=>{hide();page.value=1;void load();},{immediate:true});
function attach(){open({title:'保存凭据',description:'秘密先暂存，再绑定到当前资源；暂存 5 分钟过期。失败后先核对安全状态，不会自动重放秘密。',fields:[{key:'kind',label:'凭据类型',required:true,options:opts(['password','api_key','certificate_pin','other']),initial:'password'},{key:'secret_value',label:'秘密内容',type:'password',required:true,max:16000}],onSubmit:async v=>{
 let stage='';try{const s=await mutate<DTO<'Stage2SecretStageView'>>(`/resources/${props.resource.id}/secret-stages`,{kind:v.kind,secret_value:v.secret_value,purpose:'attach'});stage=s.stage_token;v.secret_value='';const result=await mutate<DTO<'Stage2CredentialOperationView'>>(`/resources/${props.resource.id}/credentials`,{expected_version:props.resource.version,stage_token:stage,kind:v.kind});if(result.status==='failed')throw new Error('凭据保存未成功，请核对安全状态后重新暂存。');notice.value='凭据已加密保存；查看仍需要有效授权和近期身份验证。';emit('changed');await load();}finally{stage='';v.secret_value='';}
 }});}
function reveal(row:DTO<'Stage2CredentialMetadata'>){hide();open({title:'受控查看凭据',description:'需要当前本人有效的查看授权及近期身份验证；管理员身份不会自动获得查看权限。明文最多显示 30 秒，切出页面即隐藏。',fields:[{key:'reason',label:'本次查看原因',required:true,type:'textarea'}],submitLabel:'验证授权并查看',onSubmit:async v=>{const r=await mutate<DTO<'Stage2CredentialRevealView'>>(`/credentials/${row.id}/actions/reveal`,{reason:v.reason});secret.value=r.secret_value;revealed.value=true;timer=setTimeout(hide,30000);}});}
async function loadGrants(){if(!grantCredential.value)return;const d=await api.get<Page<DTO<'Stage2CredentialGrantView'>>>(`/credentials/${grantCredential.value.id}/grants?page=${grantPage.value}`);grants.value=d.items;grantTotal.value=d.pagination.total;grantMore.value=d.pagination.has_next;}
function listGrants(row:DTO<'Stage2CredentialMetadata'>){grantCredential.value=row;grantPage.value=1;void run(loadGrants);}
function grant(row:DTO<'Stage2CredentialMetadata'>){open({title:'授权使用凭据',description:'指定真实人员、能力与期限；查看和轮换是独立授权。',fields:[{key:'person_id',label:'被授权人',required:true,endpoint:'/people'},{key:'capability',label:'授权能力',required:true,options:opts(['view','rotate']),initial:'view'},{key:'valid_to',label:'授权到期',type:'datetime-local',required:true},{key:'reason',label:'授权依据',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/credentials/${row.id}/grants`,{...v,valid_to:new Date(v.valid_to).toISOString(),expected_version:row.version});await load();notice.value='授权已保存。';}});}
function prepare(row:DTO<'Stage2CredentialMetadata'>,action:string,grantId?:string){open({title:text(action),description:'仅准备操作；还需要创建治理事项、记录实际执行并由他人独立复核后生效。',fields:[...(action==='replace'?[{key:'secret_value',label:'新秘密内容',type:'password',required:true,max:16000}]:[]),{key:'reason',label:'变更原因',type:'textarea',required:true}],onSubmit:async v=>{let stage='';try{if(action==='replace'){const s=await mutate<DTO<'Stage2SecretStageView'>>(`/resources/${props.resource.id}/secret-stages`,{kind:row.kind,secret_value:v.secret_value,purpose:'replace'});stage=s.stage_token;v.secret_value='';}const operation=await mutate<DTO<'Stage2PreparedOperationView'>>(`/credentials/${row.id}/operations`,{action,expected_version:row.version,reason:v.reason,...(stage?{stage_token:stage}:{}),...(grantId?{grant_id:grantId}:{})});await goSaved(router,{path:'/governance',query:{resource:props.resource.id,action:action==='replace'?'rotate_credential':action==='revoke'?'revoke_credential':'revoke_credential_grant',credential:row.id,grant:grantId,operation:operation.id}});}finally{stage='';v.secret_value='';}}});}
</script>
<template><div><div class="mb-3 flex items-center justify-between gap-3"><p class="text-xs text-gray-500">列表只含安全元数据，秘密独立加密与授权。</p><button v-if="resource.capabilities.edit&&can('credential.write')" class="btn-secondary" @click="attach">保存凭据</button></div><PageState :busy="busy" :error="error" :notice="notice" :empty="!rows.length" @retry="load"/><div v-for="row in rows" :key="row.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-gray-100 py-3"><div><strong class="text-sm">{{text(row.kind)}}</strong><span class="ml-2 feishu-badge bg-gray-100">{{text(row.status)}}</span><p class="mt-1 text-xs text-gray-500">{{date(row.created_at)}} · v{{row.version}}</p></div><div class="flex flex-wrap gap-1"><button v-if="row.status==='saved'" class="btn-ghost text-xs" @click="reveal(row)">受控查看</button><template v-if="resource.capabilities.edit&&can('credential.write')"><button class="btn-ghost text-xs" @click="listGrants(row)">授权记录</button><button v-if="row.status==='saved'" class="btn-ghost text-xs" @click="grant(row)">授权</button><button v-if="row.status==='saved'" class="btn-ghost text-xs" @click="prepare(row,'replace')">轮换</button><button v-if="row.status==='saved'" class="btn-ghost text-xs" @click="prepare(row,'revoke')">撤销</button></template></div></div><Pager :page="page" :total="total" :more="more" :busy="busy" @change="page=$event;load()"/><AdminDialog :open="revealed" title="凭据临时查看" description="30 秒后隐藏；切出页面或关闭窗口会立即清除。" title-id="reveal-title" @close="hide"><div class="admin-dialog-body"><pre class="whitespace-pre-wrap break-all rounded-lg bg-gray-50 p-3 text-sm">{{secret}}</pre></div><footer class="admin-dialog-footer"><button class="btn-secondary" @click="hide">立即隐藏</button><button class="btn-primary" @click="run(async()=>{await copyText(secret);notice='已按你的操作复制到系统剪贴板。'})">复制秘密</button></footer></AdminDialog><AdminDialog :open="Boolean(grantCredential)" title="凭据授权记录" title-id="grants-title" @close="grantCredential=undefined"><div class="admin-dialog-body"><div v-for="g in grants" :key="g.id" class="border-b py-3 text-xs"><p>{{g.person_id}} · {{text(g.capability)}} · 到期 {{date(g.valid_to)}}</p><p class="mt-1 text-gray-500">{{g.reason}}</p><button v-if="grantCredential&&(!g.valid_to||new Date(g.valid_to)>new Date())" class="btn-ghost text-xs" @click="prepare(grantCredential,'revoke_grant',g.id)">申请撤销此授权</button></div><Pager :page="grantPage" :total="grantTotal" :more="grantMore" @change="grantPage=$event;run(loadGrants)"/></div></AdminDialog><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></div></template>
